package com.nextaicommerce.platform.shipping;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
import java.util.*;import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.*;import com.nextaicommerce.platform.shopify.*;import tools.jackson.databind.ObjectMapper;
class LocalFedExShippingUatTest {
 final UUID tenant=UUID.randomUUID(),store=UUID.randomUUID(),order=UUID.randomUUID(),cycle=UUID.randomUUID(),carrier=UUID.randomUUID(),quote=UUID.randomUUID();
 final LocalShopifyShippingUat cycles=mock(LocalShopifyShippingUat.class);final FedExSandboxRates provider=mock(FedExSandboxRates.class);final CarrierConnectionRepository connections=mock(CarrierConnectionRepository.class);final FedExShipmentRepository shipments=mock(FedExShipmentRepository.class);final CarrierOrderContext orders=mock(CarrierOrderContext.class);final ShopifyOrderPacking packing=mock(ShopifyOrderPacking.class);final ObjectMapper json=new ObjectMapper();final ShippingLabelCrypto crypto=new ShippingLabelCrypto(Base64.getEncoder().encodeToString(new byte[32]));final AtomicReference<FedExShipmentRepository.Shipment> row=new AtomicReference<>();LocalFedExShippingUat service;String key;final List<CarrierLabelComposer.Line> frozen=List.of(CarrierLabelComposer.Line.accountItem("Brand","0001","Product",new java.math.BigDecimal("12"),"MAIN").withPackage("Custom packaging"));
 @BeforeEach void setup(){service=new LocalFedExShippingUat(cycles,provider,connections,shipments,orders,packing,crypto,new CarrierLabelComposer(),json);when(cycles.cycle(tenant,store,order)).thenReturn(cycle);when(provider.account()).thenReturn("740561073");key=LocalShopifyShippingUat.shipmentKey(order,cycle);when(orders.accountPacking(tenant,store,order.toString())).thenReturn(frozen);row.set(shipment("RATED",null));when(shipments.list(tenant,store,key)).thenAnswer(a->List.of(row.get()));when(connections.find(tenant,carrier)).thenReturn(new CarrierConnectionRepository.Connection(carrier,"LOCAL TEST","740561073","SANDBOX","PLATFORM",1,null,null,null));var payload=json.createObjectNode();payload.putObject("accountNumber").put("value","740561073");payload.putObject("requestedShipment").putObject("recipient").putObject("address").put("postalCode","38103");when(shipments.claim(tenant,store,key,quote,"FEDEX_GROUND",1)).thenReturn(crypto.encrypt(payload.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));when(provider.ship(eq(tenant),eq(store),any())).thenReturn(new FedExPayloads.Label("000000000000",new byte[]{1,2,3}));doAnswer(a->{row.set(shipment("PURCHASED","LOCAL_HANDOFF_PENDING"));return null;}).when(shipments).purchasedUat(eq(tenant),eq(quote),anyString(),any());doAnswer(a->{row.set(shipment("PURCHASED",null));return null;}).when(shipments).localHandoffPending(tenant,quote,false);}
 FedExShipmentRepository.Shipment shipment(String state,String error){return new FedExShipmentRepository.Shipment(quote,carrier,1,key,"SANDBOX",state,json.createArrayNode(),json.valueToTree(frozen),null,error,false);}
 @Test void sandboxLabelUsesDurableClaimThenArchiveThenExistingHandoffAndReplayNeverShipsAgain(){service.purchase(tenant,store,order.toString(),quote,"FEDEX_GROUND","operator");service.purchase(tenant,store,order.toString(),quote,"FEDEX_GROUND","operator");verify(provider,times(1)).ship(eq(tenant),eq(store),any());verify(packing,times(1)).mark(eq(tenant),eq(store),eq(order),eq(true),eq("operator"),any(Runnable.class));var sequence=inOrder(shipments,provider,packing);sequence.verify(shipments).claim(tenant,store,key,quote,"FEDEX_GROUND",1);sequence.verify(provider).ship(eq(tenant),eq(store),any());sequence.verify(shipments).purchasedUat(eq(tenant),eq(quote),anyString(),any());sequence.verify(packing).mark(eq(tenant),eq(store),eq(order),eq(true),eq("operator"),any(Runnable.class));}
 @Test void stockShortageAndForeignStoreStopBeforeCarrierClaim(){when(packing.eligibility(tenant,store,order)).thenReturn("Insufficient reserved stock");assertThatThrownBy(()->service.purchase(tenant,store,order.toString(),quote,"FEDEX_GROUND","operator")).isInstanceOf(IllegalStateException.class);verify(provider,never()).ship(any(),any(),any());verify(shipments,never()).claim(any(),any(),anyString(),any(),anyString(),anyLong());assertThatThrownBy(()->service.purchase(tenant,UUID.randomUUID(),order.toString(),quote,"FEDEX_GROUND","operator")).isInstanceOf(IllegalStateException.class);}
 @Test void uncertainCarrierNeverHandsOffOrRetries(){when(provider.ship(eq(tenant),eq(store),any())).thenThrow(new FedExClient.CarrierException("Uncertain",true));assertThatThrownBy(()->service.purchase(tenant,store,order.toString(),quote,"FEDEX_GROUND","operator")).isInstanceOf(FedExClient.CarrierException.class);verify(shipments).failure(tenant,quote,true);verify(packing,never()).mark(any(),any(),any(),anyBoolean(),anyString(),any(Runnable.class));verify(provider,times(1)).ship(eq(tenant),eq(store),any());}
 @Test void savedLabelWithFailedLocalHandoffRetriesOnlyHandoffNeverCarrier(){row.set(shipment("PURCHASED","LOCAL_HANDOFF_PENDING"));service.purchase(tenant,store,order.toString(),quote,"FEDEX_GROUND","operator");verifyNoInteractions(provider);verify(packing).mark(eq(tenant),eq(store),eq(order),eq(true),eq("operator"),any(Runnable.class));verify(shipments).localHandoffPending(tenant,quote,false);}
 @Test void failureAfterLabelArchiveRemainsPendingAndRetryOnlyCompletesLocalHandoff(){doThrow(new IllegalArgumentException("Stock changed")).doNothing().when(packing).mark(eq(tenant),eq(store),eq(order),eq(true),eq("operator"),any(Runnable.class));assertThatThrownBy(()->service.purchase(tenant,store,order.toString(),quote,"FEDEX_GROUND","operator")).isInstanceOf(IllegalStateException.class).hasMessageContaining("label saved");assertThat(row.get().state()).isEqualTo("PURCHASED");assertThat(row.get().error()).isEqualTo("LOCAL_HANDOFF_PENDING");service.purchase(tenant,store,order.toString(),quote,"FEDEX_GROUND","operator");verify(provider,times(1)).ship(eq(tenant),eq(store),any());verify(packing,times(2)).mark(eq(tenant),eq(store),eq(order),eq(true),eq("operator"),any(Runnable.class));verify(shipments,never()).failure(any(),any(),anyBoolean());}
 @Test void changedMappedQuantityOrLocationCannotUseArchivedQuote(){when(orders.accountPacking(tenant,store,order.toString())).thenReturn(List.of(CarrierLabelComposer.Line.accountItem("Brand","0001","Product",new java.math.BigDecimal("12"),"F7")));assertThatThrownBy(()->service.purchase(tenant,store,order.toString(),quote,"FEDEX_GROUND","operator")).hasMessageContaining("changed");verify(provider,never()).ship(any(),any(),any());}
 @Test void obsoleteRatedSnapshotCannotSilentlyShipASyntheticRecipientAfterUpdate(){row.set(new FedExShipmentRepository.Shipment(quote,carrier,1,key,"SANDBOX","RATED",json.createArrayNode(),json.createArrayNode(),null,null,false));assertThatThrownBy(()->service.purchase(tenant,store,order.toString(),quote,"FEDEX_GROUND","operator")).hasMessageContaining("fresh rates");verify(provider,never()).ship(any(),any(),any());}
 @Test void quoteEncryptsActualRecipientAndFreezesMappedItemsBeforeCarrierPurchase(){
  var sender=new BuyShippingRepository.Address(UUID.randomUUID(),"Own sender","Sender",null,"Own Street",null,null,"City","TN","38103","US","9015550100",null,true);
  var context=new BuyShippingService.Context(null,null,List.of(),List.of(sender),List.of(),null,List.of(),Map.of());when(orders.rateOnlyContext(tenant,store,order.toString())).thenReturn(context);
  var address=new FedExPayloads.Address("Actual Recipient","9015550101","Actual Street","City","TN","38103","US",false);
  var parcel=new FedExPayloads.Parcel(java.math.BigDecimal.TEN,java.math.BigDecimal.TEN,java.math.BigDecimal.TEN,java.math.BigDecimal.ONE);
  when(provider.quote(eq(tenant),eq(store),any(),eq(address),eq(parcel))).thenReturn(new FedExSandboxRates.Quote(List.of(new FedExPayloads.Rate("FEDEX_GROUND","Ground",java.math.BigDecimal.TEN,"USD")),true,"SANDBOX",""));
  when(connections.localSandboxUat(tenant,"740561073")).thenReturn(new CarrierConnectionRepository.Connection(carrier,"TEST","740561073","SANDBOX","PLATFORM",1,null,null,null));
  service.quote(tenant,store,order.toString(),new FedExShippingService.RateOnlyInput(sender.id(),parcel,address),"operator");
  verify(shipments).quote(eq(tenant),eq(store),eq(key),any(),argThat(encrypted->{String payload=new String(crypto.decrypt(encrypted.payload(),encrypted.nonce()),java.nio.charset.StandardCharsets.UTF_8);return payload.contains("Actual Recipient")&&payload.contains("Actual Street")&&!payload.contains("Sandbox Test Recipient");}),anyList(),eq(frozen),eq("operator"));verify(provider,never()).ship(any(),any(),any());
 }
 @Test void packingComparisonIgnoresOnlyNumericScaleAndNeverRoundsOrDropsIdentity(){
  var a=List.of(CarrierLabelComposer.Line.accountItem("Brand","0001","Product",new java.math.BigDecimal("8.0000"),"MAIN"));
  assertThat(LocalFedExShippingUat.samePacking(a,List.of(CarrierLabelComposer.Line.accountItem("Brand","0001","Product",new java.math.BigDecimal("8.0"),"MAIN")))).isTrue();
  assertThat(LocalFedExShippingUat.samePacking(a,List.of(a.getFirst().withPackage("FedEx Pak Padded")))).isTrue();
  assertThat(LocalFedExShippingUat.samePacking(List.of(a.getFirst().withPackage("FedEx Envelope Standard")),List.of(a.getFirst().withPackage("FedEx Pak Padded")))).isFalse();
  for(var changed:List.of(CarrierLabelComposer.Line.accountItem("Brand","0001","Product",new java.math.BigDecimal("8.0001"),"MAIN"),CarrierLabelComposer.Line.accountItem("Brand","0001","Product",new java.math.BigDecimal("8"),"F7"),CarrierLabelComposer.Line.accountItem("Brand","1","Product",new java.math.BigDecimal("8"),"MAIN"),CarrierLabelComposer.Line.accountItem("Other","0001","Product",new java.math.BigDecimal("8"),"MAIN")))assertThat(LocalFedExShippingUat.samePacking(a,List.of(changed))).isFalse();
 }
}
